<?php
// Register a custom API route so the Panel can fetch the list of available icons dynamically
Kirby::plugin('kinetik/icon-options', [
    'api' => [
        'routes' => [
            [
                'pattern' => 'icon-options',
                'action'  => function () {
                    $icons = [];
                    $path = kirby()->root('assets') . '/icons';

                    if (is_dir($path)) {
                        $files = glob($path . '/*.svg');
                        foreach ($files as $file) {
                            $name = basename($file, '.svg');
                            // Format name for better readability (e.g., arrow-right -> Arrow Right)
                            $label = ucwords(str_replace('-', ' ', $name));
                            $icons[] = [
                                'value' => $name,
                                'text'  => $label . ' (' . $name . ')'
                            ];
                        }
                    }

                    // Sort alphabetically
                    usort($icons, function($a, $b) {
                        return strcmp($a['text'], $b['text']);
                    });

                    return $icons;
                }
            ]
        ]
    ]
]);
EOF

